// Turns the hwb report viewer (src/hwb/assets/index.html, built by `make ui`) into a JS module
// the Worker can import. Generated file is gitignored; run before dev, test and deploy.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const src = fileURLToPath(new URL("../../src/hwb/assets/index.html", import.meta.url));
const out = fileURLToPath(new URL("../src/viewer.gen.js", import.meta.url));
const html = readFileSync(src, "utf8");
const slot = '<script id="hwb-report" type="application/json">__HWB_REPORT__</script>';
if (html.split(slot).length !== 2) throw new Error(`${src} has no data slot; run make ui`);
writeFileSync(out, `// GENERATED by scripts/embed-viewer.mjs from src/hwb/assets/index.html. Do not edit.\nexport default ${JSON.stringify(html)};\n`);
console.log(`embedded viewer (${html.length} bytes) -> src/viewer.gen.js`);
